/**
 * Card data model shared by the app and the build/validation scripts.
 * `data/cards.json` is generated by `npm run build:cards` from the structure table in
 * `src/data/deck.ts` plus the hand-written text batches in `data/cards/*.json`.
 */
import type { Language } from '@/i18n/languages';

export const SUITS = ['major', 'wands', 'cups', 'swords', 'pentacles'] as const;
export type Suit = (typeof SUITS)[number];

export const ELEMENTS = ['fire', 'water', 'air', 'earth'] as const;
export type Element = (typeof ELEMENTS)[number];

export const READING_AREAS = ['love', 'career', 'money', 'health'] as const;
export type ReadingArea = (typeof READING_AREAS)[number];

export type Arcana = 'major' | 'minor';
export type Orientation = 'upright' | 'reversed';

export type CourtRank = 'page' | 'knight' | 'queen' | 'king';

export type PairedReading = Record<Orientation, string>;

/** Hand-written text for one card in one language (`data/cards/*.json`). */
export interface CardTextSource {
  name: string;
  keywords: string[];
  upright: string;
  reversed: string;
  love: PairedReading;
  career: PairedReading;
  money: PairedReading;
  /** Health & spirit — wellbeing and inner life, never medical claims. */
  health: PairedReading;
  advice: string;
}

/** Fully resolved text for one language in `data/cards.json`. */
export interface CardText extends CardTextSource {
  /** Localised suit label ("Wands", "တုတ်", "Major Arcana" …). */
  suit: string;
  /** Localised element label. */
  element: string;
  /** Localised astrological association. */
  astrology: string;
}

export interface CardSource {
  id: string;
  en: CardTextSource;
  my: CardTextSource;
}

export interface TarotCard {
  id: string;
  arcana: Arcana;
  suit: Suit;
  /** Major: 0–21. Minor: 1 (Ace) – 10, 11 Page, 12 Knight, 13 Queen, 14 King. */
  number: number;
  element: Element;
  /** File name of the 1909 Pamela Colman Smith scan on Wikimedia Commons. */
  commonsFile: string;
  en: CardText;
  my: CardText;
}

export type LocalizedCard = Omit<TarotCard, Language> & { text: CardText };
